from sage.all_cmdline import *   # import sage library

_sage_const_1 = Integer(1); _sage_const_0 = Integer(0); _sage_const_5 = Integer(5); _sage_const_2 = Integer(2)
def numtopf(num, n=False):
    if not n:
        k = _sage_const_1 
        while (k+_sage_const_1 )**(k-_sage_const_1 ) < num:
            k += _sage_const_1 
        n = k
    digits = [(num//((n+_sage_const_1 )**j))%(n+_sage_const_1 ) for j in range(n-_sage_const_1 )]
    digits.reverse()
    pps = [[(i+_sage_const_1 +sum(digits[_sage_const_0 :j]))%(n+_sage_const_1 ) for j in range(n)] for i in range(n)]
    for pp in pps:
        wipp = sorted(pp)
        ispf = all([wipp[i] <= i+_sage_const_1  for i in range(n)])
        if _sage_const_0  not in wipp and ispf:
            return pp
    return "ERROR"

def outcome_is_stinky(out, r):
    n = len(out)
    valid = True
    indices = [pair[_sage_const_1 ] for pair in sorted(list(zip(out, list(range(n)))))]
    street = [_sage_const_1 ] + [_sage_const_0 ]*(n-_sage_const_1 )

    # Keys are positions, values are sets of cars within radius of position
    # Should ideally be filled out dynamically in the for - easy to check conditions
    cars_in_radius = {i:set() for i in range(n)}
    # See if you can remove this for by starting the big for at 0
    for i in range(min(r+_sage_const_1 , n)):
        cars_in_radius[i].add(_sage_const_1 )

    for i in range(_sage_const_1 , n):
        #print(cars_in_radius)
        empties = [j for j in range(indices[i]) if street[j] == _sage_const_0 ]
        # We need (not <=) instead of (>) because our landing spot might have friendly cars to its right 
        # {} !> {}, so this also checks if this spot is not too far away from everyone
        conds = [not (cars_in_radius[e] <= cars_in_radius[indices[i]]) for e in empties]
        
        if all(conds):
            street[indices[i]] = i+_sage_const_1 
            for j in range(max(indices[i]-r, _sage_const_0 ), min(indices[i]+r+_sage_const_1 , n)):
                cars_in_radius[j].add(i+_sage_const_1 )
        else:
            valid = False
            break
    return valid

def all_stinky_outcomes(n, r):
    outs = Permutations(n-_sage_const_1 )
    stinky_outs = []
    for p in outs:
        out = [_sage_const_1 ] + [i+_sage_const_1  for i in p]
        if outcome_is_stinky(out, r):
            stinky_outs.append(out)
    return stinky_outs

